  `sent_date` TIME,
  `response_received_date` TIME,
  `other_details` TEXT,
  PRIMARY KEY (`document_id`)
);

CREATE TABLE `Grants` (
  `grant_id` NUMBER,
  `organisation_id` NUMBER REFERENCES `Organisations`(`organisation_id`),
  `grant_amount` NUMBER,
  `grant_start_date` TIME,
  `grant_end_date` TIME,
  `other_details` TEXT,
  PRIMARY KEY (`grant_id`)
);

